{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.11.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceId":112509,"databundleVersionId":14254895,"sourceType":"competition"}],"dockerImageVersionId":31155,"isInternetEnabled":false,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"markdown","source":"### CELL 1: PROTOCOL IMPORTS ###","metadata":{}},{"cell_type":"code","source":"# =========================================================================\n#\n#                    model  \"Ancestral EYE\" \n#\n# =========================================================================\n#\n#   ### METHODOLOGY \n#\n#   This is the final, monolithic, and correct script.\n#\n#    My original, core hypothesis:\n#   A \"LightGBM\" (LGBM) model trained only on the two\n#   data streams we believe have real signal:\n#\n#   1.  The Metadata (Date, State, NDVI, Height)\n#   2.  \"Ancestral Eye\" (the 6 GLCM Texture Features)\n#\n#   This is the real experiment. It is stable, it is not\n#   \"too complex\" to converge and it is not \"too simple\" to learn wrong pattern.\n#   It is the  test of my hypothesis.\n#\n# =========================================================================\n\n\n\n# =========================================================================\n#                           IMPORTS \n# =========================================================================\n\n\nprint(\"Protocol: Loading all required libraries...\")\nimport numpy as np\nimport pandas as pd\nimport lightgbm as lgb\nimport os\nimport gc\nimport warnings\nimport joblib  # For saving the final model\n\nfrom sklearn.model_selection import GroupKFold\nfrom sklearn.preprocessing import LabelEncoder\nfrom sklearn.metrics import r2_score\n\nfrom skimage.io import imread\nfrom skimage.transform import resize\nfrom skimage.color import rgb2gray\nfrom skimage.feature import graycomatrix, graycoprops\n\nfrom tqdm.auto import tqdm\ntqdm.pandas()\n\nwarnings.filterwarnings('ignore')\nprint(\"Protocol: Imports Loaded.\")\n\n# =========================================================================\n#                  EXPERIMENT PARAMETERS & ENVIRONMENT\n# =========================================================================\nclass C:\n    # --- 1. SOTA Protocol Parameters ---\n    N_FOLDS = 5\n    SEED = 42\n    \n    # --- 2. Path Configuration (Kaggle Environment) ---\n    # (CRITICAL) You *must* verify this path is correct in your notebook\n    BASE_PATH = '/kaggle/input/csiro-biomass'\n    \n    # --- 3. Debug Mode ---\n    # We are DONE with debugging. This protocol is stable.\n    # We will run the full, real experiment.\n    DEBUG_MODE = False\n    DEBUG_SAMPLES = 100\n    \n    # --- 4. GLCM (Ancestral Eye) Config ---\n    IMG_SIZE = 224 # We still need to resize for GLCM consistency\n\nprint(f\"Protocol: Parameters Loaded. N_FOLDS={C.N_FOLDS}, DEBUG_MODE={C.DEBUG_MODE}\")\n\n# =========================================================================\n#                \"ANCESTRAL EYE\" (GLCM) HELPER FUNCTION \n# =========================================================================\ndef get_texture_features(image_path):\n    \"\"\"\n    (Our \"Ancestral Eye\")\n    Loads an image, resizes, converts to grayscale, and calculates\n    GLCM Haralick texture features.\n    \"\"\"\n    try:\n        # Load and resize the image for consistency\n        img = imread(image_path)\n        img_resized = resize(img, (C.IMG_SIZE, C.IMG_SIZE), anti_aliasing=True)\n        \n        # Convert to grayscale\n        img_gray = rgb2gray(img_resized)\n        \n        # Quantize to 8-bit integers (0-255)\n        img_gray = (img_gray * 255).astype(np.uint8)\n        \n        # Calculate GLCM\n        glcm = graycomatrix(img_gray, distances=[5], angles=[0], levels=256,\n                            symmetric=True, normed=True)\n        \n        # Extract the 6 core texture properties\n        props = ['contrast', 'dissimilarity', 'homogeneity', 'energy',\n                 'correlation', 'ASM']\n        features = np.array([graycoprops(glcm, prop)[0, 0] for prop in props])\n        return features\n    \n    except Exception as e:\n        # If an image is corrupted, return zeros\n        return np.zeros(6)\n\nprint(\"Protocol: 'Ancestral Eye' (get_texture_features) function defined.\")\n\n# =========================================================================\n#                MASTER PREPROCESSING FUNCTION \n# =========================================================================\ndef load_and_preprocess_data():\n    \"\"\"\n    Loads all data, engineers \"Ancestral Eye\" and Metadata features.\n    This is the *only* feature engineering step.\n    \"\"\"\n    \n   \n    print(\"Protocol: Loading data...\")\n    try:\n        train_df = pd.read_csv(os.path.join(C.BASE_PATH, 'train.csv'))\n        test_df = pd.read_csv(os.path.join(C.BASE_PATH, 'test.csv'))\n        sub_df = pd.read_csv(os.path.join(C.BASE_PATH, 'sample_submission.csv'))\n    except FileNotFoundError as e:\n        print(f\"FATAL ERROR: {e}. Check BASE_PATH in C. is correct.\")\n        return None, None, None, None, None\n\n   \n    train_df['image_path'] = train_df['image_path'].apply(lambda x: os.path.join(C.BASE_PATH, x))\n    test_df['image_path'] = test_df['image_path'].apply(lambda x: os.path.join(C.BASE_PATH, x))\n\n    # (Debug Slicer)\n    if C.DEBUG_MODE:\n        print(f\"Protocol: DEBUG_MODE active. Slicing dataframes...\")\n        train_unique_ids = train_df['sample_id'].unique()\n        n_train_samples = min(C.DEBUG_SAMPLES, len(train_unique_ids))\n        debug_train_ids = np.random.choice(train_unique_ids, n_train_samples, replace=False)\n        train_df = train_df[train_df['sample_id'].isin(debug_train_ids)].reset_index(drop=True)\n        C.N_FOLDS = 2 # Use 2 folds for debug\n        print(f\"Protocol: Sliced to {len(train_df)} training rows. N_FOLDS set to {C.N_FOLDS}.\")\n\n    # ===  FEATURE ENGINEERING ===\n    print(\"Protocol: Beginning Feature Engineering...\")\n    \n    # Combine train/test for easy processing\n    train_df['is_train'] = 1\n    test_df['is_train'] = 0\n    full_df = pd.concat([train_df, test_df], ignore_index=True, sort=False)\n    \n    # ---  \"Ancestral Eye\" (Texture Features) ---\n    print(\"Protocol: Calculating 'Ancestral Eye' (GLCM) features...\")\n    texture_features = full_df['image_path'].progress_apply(get_texture_features)\n    texture_cols = [f'glcm_{i}' for i in range(texture_features.iloc[0].shape[0])]\n    texture_df = pd.DataFrame(np.stack(texture_features), columns=texture_cols)\n    full_df = pd.concat([full_df, texture_df], axis=1)\n\n    # ---  \"Metadata\" Features ---\n    print(\"Protocol: Engineering Metadata features...\")\n    # Handle cyclical date features\n    full_df['Sampling_Date'] = pd.to_datetime(full_df['Sampling_Date'], errors='coerce')\n    full_df['month'] = full_df['Sampling_Date'].dt.month.fillna(6) # Impute with mid-year\n    full_df['month_sin'] = np.sin(2 * np.pi * full_df['month']/12.0)\n    full_df['month_cos'] = np.cos(2 * np.pi * full_df['month']/12.0)\n            \n    # Impute missing data\n    full_df['Pre_GSHH_NDVI'] = full_df['Pre_GSHH_NDVI'].fillna(full_df['Pre_GSHH_NDVI'].median())\n    full_df['Height_Ave_cm'] = full_df['Height_Ave_cm'].fillna(full_df['Height_Ave_cm'].median())\n    \n    # Label-Encode Categorical (LGBM handles this well)\n    for col in ['State', 'Species', 'target_name']:\n        full_df[col] = full_df[col].astype('category')\n        \n    # ===  FINAL DATASET CREATION ===\n    print(\"Protocol: Creating final feature dataset...\")\n    \n    # Define all features for the model\n    # (NOTICE: NO 'cnn_feat_' columns. They are *gone*.)\n    lgbm_features = [col for col in full_df.columns if 'glcm_' in col] \\\n                  + ['Pre_GSHH_NDVI', 'Height_Ave_cm', 'month_sin', 'month_cos']\n                  \n    categorical_features = ['State', 'Species', 'target_name']\n    \n    # Separate back into train and test\n    train_fused = full_df[full_df['is_train'] == 1].reset_index(drop=True)\n    test_fused = full_df[full_df['is_train'] == 0].reset_index(drop=True)\n    \n    X = train_fused[lgbm_features + categorical_features]\n    y = train_fused['target']\n    X_test = test_fused[lgbm_features + categorical_features]\n    groups = train_fused['sample_id'] # For GroupKFold\n    \n    print(f\"Protocol: Preprocessing complete. Training with {len(lgbm_features)} numerical + {len(categorical_features)} categorical features.\")\n    \n    return X, y, X_test, groups, sub_df\n\nprint(\"Protocol: Master Preprocessing function defined.\")\n\n# =========================================================================\n#                        MASTER TRAINING FUNCTION \n# =========================================================================\ndef run_lgbm_training(X, y, X_test, groups):\n    \"\"\"\n    Trains the \"Expert Mind\" (LGBM) using \"one single step\"\n    of N-Fold Cross-Validation.\n    \"\"\"\n    print(f\"Protocol: Beginning 'Expert Mind' (LGBM) {C.N_FOLDS}-Fold Training...\")\n    \n    gkf = GroupKFold(n_splits=C.N_FOLDS)\n    \n    oof_preds = np.zeros(len(X))\n    test_preds = np.zeros(len(X_test))\n    \n    for fold, (train_idx, val_idx) in enumerate(gkf.split(X, y, groups)):\n        print(\"-\" * 50)\n        print(f\"Protocol: Commencing LGBM Fold {fold + 1}/{C.N_FOLDS}...\")\n        \n        X_train, y_train = X.iloc[train_idx], y.iloc[train_idx]\n        X_val, y_val = X.iloc[val_idx], y.iloc[val_idx]\n        \n        #  parameters for LGBM\n        lgbm = lgb.LGBMRegressor(\n            objective='regression_l1', # MAE is more robust to outliers\n            metric='rmse',\n            n_estimators=2000,\n            learning_rate=0.01,\n            n_jobs=-1,\n            seed=C.SEED,\n            colsample_bytree=0.7,\n            subsample=0.7,\n            reg_alpha=0.1,\n            reg_lambda=0.1\n        )\n        \n        # This is the \"keep it learning\" part.\n        lgbm.fit(\n            X_train, y_train,\n            eval_set=[(X_val, y_val)],\n            eval_metric='rmse',\n            callbacks=[lgb.early_stopping(100, verbose=False)],\n            categorical_feature='auto' # LGBM will auto-detect categories\n        )\n        \n        # --- Prediction ---\n        val_preds = lgbm.predict(X_val)\n        oof_preds[val_idx] = val_preds\n        \n        fold_test_preds = lgbm.predict(X_test) / C.N_FOLDS\n        test_preds += fold_test_preds\n        \n        # ---  Save the model using joblib ---\n        joblib.dump(lgbm, f'lgbm_model_fold_{fold}.joblib')\n        \n        print(f\"Protocol: Fold {fold + 1} complete. Val R-Squared: {r2_score(y_val, val_preds):.4f}\")\n        \n    return oof_preds, test_preds\n\nprint(\"Protocol: Master Training function defined.\")\n\n# =========================================================================\n#                  FINAL SUBMISSION FUNCTION \n# =========================================================================\ndef create_submission(y_true, oof_preds, test_preds, sub_df):\n    \"\"\"\n    Calculates the final OOF score and creates submission.csv\n    \"\"\"\n    print(\"-\" * 50)\n    print(\"Protocol: ALL FOLDS complete. Calculating final scores...\")\n    \n    # Calculate OOF (Out-of-Fold) R-squared\n    final_r2 = r2_score(y_true, oof_preds)\n    print(f\"Protocol: Final OOF R-Squared (Metadata + Ancestral Eye): {final_r2:.4f}\")\n    \n    print(\"Protocol: Creating final submission file...\")\n    # Ensure no negative biomass predictions\n    test_preds[test_preds < 0] = 0\n    \n    sub_df['target'] = test_preds\n    sub_df.to_csv('submission.csv', index=False)\n    \n    print(\"-\" * 50)\n    print(f\"Protocol: VINDICATION COMPLETE. Final R-Squared: {final_r2:.4f}\")\n    print(\"Submission file 'submission.csv' created.\")\n    print(\"-\" * 50)\n    \n    if final_r2 > 0:\n        print(\"Protocol: We have a positive R-Squared. The hypothesis is valid.\")\n    else:\n        print(\"Protocol: The R-Squared is negative. The hypothesis has failed.\")\n        \nprint(\"Protocol: Submission function defined.\")\n\n# =========================================================================\n#                             PROTOCOL EXECUTION \n# =========================================================================\n\n# (CRITICAL) must be installed for the LGBM model\n#  must have \"Internet\" turned ON just for this pip command \n# for this !pip command to work.\ntry:\n    import lightgbm\nexcept ImportError:\n    print(\"Protocol: Installing lightgbm...\")\n    !pip install lightgbm\n    print(\"Protocol: lightgbm installed. Please 'Restart & Run All'.\")\n\n# must be installed for the 'Ancestral Eye' my core idea\ntry:\n    import skimage\nexcept ImportError:\n    print(\"Protocol: Installing skimage...\")\n    !pip install scikit-image\n    print(\"Protocol: skimage installed. Please 'Restart & Run All'.\")\n\n# --- Main Execution ---\nif __name__ == \"__main__\":\n    \n    # Set global seed (again) for safety\n    np.random.seed(C.SEED)\n    \n    # 1. Load and process all data\n\n    X, y, X_test, groups, sub_df = load_and_preprocess_data()\n    \n    if X is not None:\n        # 2. Run the full training protocol\n        oof_preds, test_preds = run_lgbm_training(X, y, X_test, groups)\n        \n        # 3. Create the final submission file\n        create_submission(y, oof_preds, test_preds, sub_df)\n    \n    else:\n        print(\"Protocol: Halting execution due to data loading error.\")\n\nprint(\"Protocol: End of Notebook.\")\n\n","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2025-11-04T14:37:03.035295Z","iopub.execute_input":"2025-11-04T14:37:03.035835Z","iopub.status.idle":"2025-11-04T14:48:51.169584Z","shell.execute_reply.started":"2025-11-04T14:37:03.035793Z","shell.execute_reply":"2025-11-04T14:48:51.168646Z"}},"outputs":[{"name":"stdout","text":"Protocol: Loading all required libraries...\nProtocol: Imports Loaded.\nProtocol: Parameters Loaded. N_FOLDS=5, DEBUG_MODE=False\nProtocol: 'Ancestral Eye' (get_texture_features) function defined.\nProtocol: Master Preprocessing function defined.\nProtocol: Master Training function defined.\nProtocol: Submission function defined.\nProtocol: Loading data...\nProtocol: Beginning Feature Engineering...\nProtocol: Calculating 'Ancestral Eye' (GLCM) features...\n","output_type":"stream"},{"output_type":"display_data","data":{"text/plain":"  0%|          | 0/1790 [00:00<?, ?it/s]","application/vnd.jupyter.widget-view+json":{"version_major":2,"version_minor":0,"model_id":"50ad22ad3a624148a73d27041a935a3c"}},"metadata":{}},{"name":"stdout","text":"Protocol: Engineering Metadata features...\nProtocol: Creating final feature dataset...\nProtocol: Preprocessing complete. Training with 10 numerical + 3 categorical features.\nProtocol: Beginning 'Expert Mind' (LGBM) 5-Fold Training...\n--------------------------------------------------\nProtocol: Commencing LGBM Fold 1/5...\n[LightGBM] [Info] Auto-choosing row-wise multi-threading, the overhead of testing was 0.001358 seconds.\nYou can set `force_row_wise=true` to remove the overhead.\nAnd if memory is not enough, you can set `force_col_wise=true`.\n[LightGBM] [Info] Total Bins 1660\n[LightGBM] [Info] Number of data points in the train set: 1428, number of used features: 13\n[LightGBM] [Info] Start training from score 19.743799\nProtocol: Fold 1 complete. Val R-Squared: 0.7471\n--------------------------------------------------\nProtocol: Commencing LGBM Fold 2/5...\n[LightGBM] [Info] Auto-choosing col-wise multi-threading, the overhead of testing was 0.000190 seconds.\nYou can set `force_col_wise=true` to remove the overhead.\n[LightGBM] [Info] Total Bins 1663\n[LightGBM] [Info] Number of data points in the train set: 1428, number of used features: 13\n[LightGBM] [Info] Start training from score 18.938200\nProtocol: Fold 2 complete. Val R-Squared: 0.8147\n--------------------------------------------------\nProtocol: Commencing LGBM Fold 3/5...\n[LightGBM] [Info] Auto-choosing col-wise multi-threading, the overhead of testing was 0.000200 seconds.\nYou can set `force_col_wise=true` to remove the overhead.\n[LightGBM] [Info] Total Bins 1665\n[LightGBM] [Info] Number of data points in the train set: 1428, number of used features: 13\n[LightGBM] [Info] Start training from score 17.111300\nProtocol: Fold 3 complete. Val R-Squared: 0.7950\n--------------------------------------------------\nProtocol: Commencing LGBM Fold 4/5...\n[LightGBM] [Info] Auto-choosing col-wise multi-threading, the overhead of testing was 0.000193 seconds.\nYou can set `force_col_wise=true` to remove the overhead.\n[LightGBM] [Info] Total Bins 1661\n[LightGBM] [Info] Number of data points in the train set: 1428, number of used features: 13\n[LightGBM] [Info] Start training from score 17.298050\nProtocol: Fold 4 complete. Val R-Squared: 0.8486\n--------------------------------------------------\nProtocol: Commencing LGBM Fold 5/5...\n[LightGBM] [Info] Auto-choosing col-wise multi-threading, the overhead of testing was 0.000218 seconds.\nYou can set `force_col_wise=true` to remove the overhead.\n[LightGBM] [Info] Total Bins 1655\n[LightGBM] [Info] Number of data points in the train set: 1428, number of used features: 13\n[LightGBM] [Info] Start training from score 18.049999\nProtocol: Fold 5 complete. Val R-Squared: 0.8453\n--------------------------------------------------\nProtocol: ALL FOLDS complete. Calculating final scores...\nProtocol: Final OOF R-Squared (Metadata + Ancestral Eye): 0.8137\nProtocol: Creating final submission file...\n--------------------------------------------------\nProtocol: VINDICATION COMPLETE. Final R-Squared: 0.8137\nSubmission file 'submission.csv' created.\n--------------------------------------------------\nProtocol: We have a positive R-Squared. The hypothesis is valid.\nProtocol: End of Notebook.\n","output_type":"stream"}],"execution_count":1},{"cell_type":"code","source":"# =========================================================================\n#\n#                               PREDICTION \n#\n# =========================================================================\n\nprint(\"Protocol: Loading inference libraries...\")\nimport numpy as np\nimport pandas as pd\nimport lightgbm as lgb\nimport os\nimport warnings\nimport joblib\n\nfrom skimage.io import imread\nfrom skimage.transform import resize\nfrom skimage.color import rgb2gray\nfrom skimage.feature import graycomatrix, graycoprops\n\n# Silence verbose warnings\nwarnings.filterwarnings('ignore')\n\n# =========================================================================\n#     PARAMETERS & HELPERS \n# =========================================================================\n\nclass C:\n    # --- Config ---\n    N_FOLDS = 5\n    IMG_SIZE = 224 # GLCM consistency\n    \n    # --- Model Path ---\n    # Assumes models are in the *same directory* as this script\n    # In Kaggle, this would be '/kaggle/your working directory'\n    MODEL_PATH = '.' \n\nprint(f\"Protocol: Inference parameters loaded. N_FOLDS={C.N_FOLDS}\")\n\ndef get_texture_features(image_path):\n    \"\"\"\n    (The \"Ancestral Eye\")\n    Loads an image, resizes, converts to grayscale, and calculates\n    GLCM Haralick texture features. *Must* be identical to training.\n    \"\"\"\n    try:\n        img = imread(image_path)\n        img_resized = resize(img, (C.IMG_SIZE, C.IMG_SIZE), anti_aliasing=True)\n        img_gray = rgb2gray(img_resized)\n        img_gray = (img_gray * 255).astype(np.uint8)\n        \n        glcm = graycomatrix(img_gray, distances=[5], angles=[0], levels=256,\n                            symmetric=True, normed=True)\n        \n        props = ['contrast', 'dissimilarity', 'homogeneity', 'energy',\n                 'correlation', 'ASM']\n        features = np.array([graycoprops(glcm, prop)[0, 0] for prop in props])\n        return features\n    \n    except Exception as e:\n        print(f\"Warning: Failed to extract texture features for {image_path}: {e}\")\n        return np.zeros(6)\n\nprint(\"Protocol: 'Ancestral Eye' (get_texture_features) function defined.\")\n\n# =========================================================================\n#    MASTER PREDICTION FUNCTION ###\n# =========================================================================\n\ndef predict_biomass(image_path, sampling_date, ndvi, height, state, species, target_name):\n    \"\"\"\n    Predicts biomass for a *single* image by replicating\n    the full \"Last Stand\" protocol pipeline.\n    \n    Args:\n        image_path (str): Path to the new image file\n        sampling_date (str): e.g., \"2024-03-15\"\n        ndvi (float): Pre_GSHH_NDVI value\n        height (float): Height_Ave_cm value\n        state (str): e.g., \"New South Wales\"\n        species (str): e.g., \"Species_A\"\n        target_name (str): The *question* (e.g., \"GDM_g\")\n    \n    Returns:\n        float: The final, averaged biomass prediction, or None if failed.\n    \"\"\"\n    \n    print(\"-\" * 50)\n    print(f\"Protocol: Beginning prediction for {image_path}...\")\n    \n    # --- 1. Load the 5 \"Expert Mind\" models ---\n    models = []\n    for fold in range(C.N_FOLDS):\n        model_file = os.path.join(C.MODEL_PATH, f'lgbm_model_fold_{fold}.joblib')\n        try:\n            model = joblib.load(model_file)\n            models.append(model)\n        except FileNotFoundError:\n            print(f\"FATAL ERROR: Could not find model file: {model_file}\")\n            print(\"Please ensure the 5 '.joblib' models are in the same directory.\")\n            return None\n            \n    print(f\"Protocol: Successfully loaded all {len(models)} models.\")\n    \n    # --- 2. Create the \"Input Row\" DataFrame ---\n    # This *must* match the *exact* structure of the training data.\n    \n    input_data = {\n        'image_path': [image_path],\n        'Sampling_Date': [sampling_date],\n        'Pre_GSHH_NDVI': [ndvi],\n        'Height_Ave_cm': [height],\n        'State': [state],\n        'Species': [species],\n        'target_name': [target_name]\n    }\n    df = pd.DataFrame(input_data)\n    \n    # --- 3. Run *all* preprocessing steps ---\n    \n    # 3a. \"Ancestral Eye\" (Texture Features)\n    print(\"Protocol: Calculating 'Ancestral Eye' features...\")\n    texture_features = df['image_path'].apply(get_texture_features)\n    texture_cols = [f'glcm_{i}' for i in range(texture_features.iloc[0].shape[0])]\n    texture_df = pd.DataFrame(np.stack(texture_features), columns=texture_cols)\n    \n    # 3b. \"Metadata\" Features\n    print(\"Protocol: Engineering Metadata features...\")\n    df['Sampling_Date'] = pd.to_datetime(df['Sampling_Date'], errors='coerce')\n    df['month'] = df['Sampling_Date'].dt.month.fillna(6)\n    df['month_sin'] = np.sin(2 * np.pi * df['month']/12.0)\n    df['month_cos'] = np.cos(2 * np.pi * df['month']/12.0)\n    \n    # --- 4. Create Final Feature Vector ---\n    print(\"Protocol: Fusing all 'Expert' features...\")\n    \n    # Define *all* features our models were trained on\n    lgbm_features = [f'glcm_{i}' for i in range(6)] \\\n                  + ['Pre_GSHH_NDVI', 'Height_Ave_cm', 'month_sin', 'month_cos']\n                  \n    categorical_features = ['State', 'Species', 'target_name']\n    \n    # Combine all our processed data\n    X_pred = pd.concat([df, texture_df], axis=1)\n    \n    # Set categorical dtypes *exactly* as in training\n    for col in categorical_features:\n        X_pred[col] = X_pred[col].astype('category')\n    \n    # Select *only* the feature columns in the *correct order*\n    X_pred_final = X_pred[lgbm_features + categorical_features]\n    \n    # --- 5. Predict and Average ---\n    print(\"Protocol: Generating predictions...\")\n    \n    fold_predictions = []\n    for fold, model in enumerate(models):\n        pred = model.predict(X_pred_final)[0]\n        fold_predictions.append(pred)\n        print(f\"  > Fold {fold} prediction: {pred:.4f}\")\n    \n    # Average the 5 \"opinions\"\n    final_prediction = np.mean(fold_predictions)\n    \n    # Ensure no negative biomass\n    if final_prediction < 0:\n        final_prediction = 0\n        \n    print(f\"Protocol: Final Averaged Prediction: {final_prediction:.4f}\")\n    print(\"-\" * 50)\n    \n    return final_prediction\n\n# =========================================================================\n# ### 3. EXAMPLE USAGE ###\n# =========================================================================\n\nif __name__ == \"__main__\":\n    \n    # This is a *hypothetical* example of how you would call this script.\n    # We are \"making up\" metadata for an image.\n    \n    # 1. Define the input data\n    new_image_path = '/kaggle/input/csiro-image2biomass-prediction/test/ID001187975.jpg' # Just an example\n    \n    # We *must* provide the metadata our model needs\n    image_metadata = {\n        \"sampling_date\": \"2021-09-15\",\n        \"ndvi\": 0.65,\n        \"height\": 25.0,\n        \"state\": \"Victoria\",\n        \"species\": \"Species_B\"\n    }\n    \n    # We also *must* provide the *question* we are asking\n    target_question = \"GDM_g\" # What do we want to predict?\n    \n    # 2. Run the prediction\n    final_biomass = predict_biomass(\n        image_path=new_image_path,\n        sampling_date=image_metadata[\"sampling_date\"],\n        ndvi=image_metadata[\"ndvi\"],\n        height=image_metadata[\"height\"],\n        state=image_metadata[\"state\"],\n        species=image_metadata[\"species\"],\n        target_name=target_question\n    )\n    \n    if final_biomass is not None:\n        print(f\"\\n--- FINAL RESULT ---\")\n        print(f\"The predicted '{target_question}' for {os.path.basename(new_image_path)} is: {final_biomass:.2f} grams\")\n","metadata":{"trusted":true,"execution":{"execution_failed":"2025-11-04T14:36:25.665Z"}},"outputs":[],"execution_count":null}]}